package ru.kryuch.krtg.searcher.controller;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.ModelAttribute;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestMapping;import ru.kryuch.krtg.searcher.dto.SettingItemView;import ru.kryuch.krtg.searcher.dto.SettingsWrapper;import ru.kryuch.krtg.searcher.service.SettingService;import ru.kryuch.krtg.searcher.service.VacancyService;import java.util.HashMap;import java.util.List;import java.util.Map;@Controller@RequiredArgsConstructor@RequestMapping("/settings")public class SettingsController {    private final SettingService settingService;    @GetMapping("/")    public String index(Model model) {        Map<String, List <SettingItemView> > settingItemViews = new HashMap<>();        settingItemViews.put(                "tabs-cron",                List.of(                        new SettingItemView("cron_enable", "Использование", true),                        new SettingItemView("cron_time", "Строка времени", false),                        new SettingItemView("term", "Шаблон поиска", true),                        new SettingItemView("cron_chats_count", "Число чатов в одной операции крона", false),                        new SettingItemView("max_day", "После игнора", true),                        new SettingItemView("cron_lastmessage", "Последнее сообщение", false),                        new SettingItemView("cron_newmessage", "Новое сообщение", true),                        new SettingItemView("cron_lastrun", "Последний запуск", false)                ));        settingItemViews.put(                "tabs-folder",                List.of(                        new SettingItemView("folder_enable", "Использование", true),                        new SettingItemView("add_to_folder", "Добавлять в папку новых", true),                        new SettingItemView("folder", "Название", false)                )        );        model.addAttribute("views", settingItemViews);        model.addAttribute("items", new SettingsWrapper(settingService.getAll()));        model.addAttribute("page", "settings");        return "index";    }    @PostMapping(value = "/save")    public String save(@ModelAttribute SettingsWrapper values, BindingResult result, Model model) {        settingService.save(values);        return "redirect:/settings/";    }}